package com.tradingdesk.forex.websocket;

import com.tradingdesk.forex.entity.TradingOrder;
import com.tradingdesk.forex.service.OrderExecutionService;
import org.springframework.messaging.handler.annotation.DestinationVariable;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Controller;
import java.security.Principal;
import java.util.UUID;

@Controller
public class OrderCancelWebSocketHandler {

    private final OrderExecutionService orderService;
    private final SimpMessagingTemplate messagingTemplate;

    public OrderCancelWebSocketHandler(OrderExecutionService orderService, SimpMessagingTemplate messagingTemplate) {
        this.orderService = orderService;
        this.messagingTemplate = messagingTemplate;
    }

    @MessageMapping("/trade/orders/{orderId}/cancel")
    public void cancelLimitOrder(
            @DestinationVariable UUID orderId,
            Principal principal) {
        TradingOrder order = orderService.getOrderById(orderId);
        if (!order.getTraderUsername().equals(principal.getName())) {
            throw new AccessDeniedException("Trader " + principal.getName() + " does not own order " + orderId);
        }
        orderService.cancelOrder(orderId);
        messagingTemplate.convertAndSendToUser(principal.getName(), "/queue/orders/cancelled", orderId.toString());
    }
}
